#!/usr/bin/env python3
"""Offline one-before/one-after C9 decision; never changes original measurements."""
import collections,hashlib,json,pathlib,sys
b=pathlib.Path(sys.argv[1]);runs={'baseline':b/'baseline-mysql-v2','rejected_A':b/'freshafter-mysql-v2'}
def load(p):return json.loads(p.read_text())
def delay(p):
 counts=collections.Counter();cpu=0;n=0
 with (p/'peer/requests.jsonl').open() as f:
  for l in f:
   r=json.loads(l)
   if r.get('event')=='provider_delay_applied':counts[r['delay_ms']]+=1
   if 'thread_CPU_ns'in r:cpu+=r['thread_CPU_ns'];n+=1
 return {'applied_delay_ms_counts_including_warmup':dict(counts),'Mock_method_thread_CPU_seconds_lowerbound':cpu/1e9,'Mock_CPU_samples':n,'scope':'samePythonPIDtotalincludesboth; threadCPUlowerboundnotadditional; fixed500msinterval8s restores20msbeforedrain'}
arm={}
for label,p in runs.items():
 strict=load(b/(p.name+'-strict')/'summary.json');metrics=load(p/'baseline-offline-summary.json');profile=load(p/'profile-interior-summary.json');metadata=load(p/'component-metadata-summary.json');gauges=load(p/'stage-gauges-and-activity.json');result=load(p/'result.json')
 arm[label]={'product_commit':load(p/'plan.json')['source_commit'],'observer_sha256':load(p/'plan.json')['binary_sha256'],'input_and_driver_match':{'input_sha256':load(p/'plan.json')['frozen_input_plan_sha256'],'driver_sha256':load(p/'plan.json')['runner_sha256']},'result':{k:result[k] for k in ('failure','exit_code','clean_shutdown','quiet','offered_messages','offered_targets','request_failures','planned_not_offered_messages')},'strict':strict,'cycles':metrics['cycles'],'idle_resources':metrics['idle_resources'],'resource_totals':metrics['resource_totals'],'producer':metrics['producer'],'global_cumulative_peak_gauges':gauges['global_cumulative_peak_gauges'],'stage_activity_and_gauges':gauges['phases'],'connection_boundary_receipts':gauges['all_connection_boundary_receipts'],'peer':delay(p),'DB_cgroup_CPU_seconds_boundary_delta':metadata['DB_cgroup_CPU_seconds_boundary_delta'],'DB_global_numeric_boundary_delta':metadata['DB_global_numeric_boundary_delta'],'DB_boundary_memory':[{'label':x['label'],'memory_current_bytes':x['DB_cgroup_memory_current_bytes'],'anon_bytes':x['DB_cgroup_anon_bytes'],'filecache_bytes':x['DB_cgroup_filecache_bytes']} for x in metadata['boundaries']],'profile':profile,'Usage_SQL_calls_per_bundle_source_bound':4 if label=='baseline' else 3}
for key in ('input_sha256','driver_sha256'):assert arm['baseline']['input_and_driver_match'][key]==arm['rejected_A']['input_and_driver_match'][key]
comparisons={}
for cycle in ('cycle0','cycle1'):
 x=arm['baseline']['cycles'][cycle];y=arm['rejected_A']['cycles'][cycle]
 comparisons[cycle]={'p95_ms_delta':y['offer_to_target_commit_ms']['p95']-x['offer_to_target_commit_ms']['p95'],'p99_ms_delta':y['offer_to_target_commit_ms']['p99']-x['offer_to_target_commit_ms']['p99'],'burst_drain_seconds_delta':y['stages']['burst_256']['drain_from_last_offer_seconds']-x['stages']['burst_256']['drain_from_last_offer_seconds'],'cycle_last_COMMIT_seconds_delta':y['last_commit_from_first_offer_seconds']-x['last_commit_from_first_offer_seconds']}
variation={'p95_ms':abs(arm['baseline']['cycles']['cycle1']['offer_to_target_commit_ms']['p95']-arm['baseline']['cycles']['cycle0']['offer_to_target_commit_ms']['p95']),'p99_ms':abs(arm['baseline']['cycles']['cycle1']['offer_to_target_commit_ms']['p99']-arm['baseline']['cycles']['cycle0']['offer_to_target_commit_ms']['p99']),'burst_drain_seconds':abs(arm['baseline']['cycles']['cycle1']['stages']['burst_256']['drain_from_last_offer_seconds']-arm['baseline']['cycles']['cycle0']['stages']['burst_256']['drain_from_last_offer_seconds'])}
out={'status':'A_REJECTED_REVERT_DECIDED_BY_ROOT_NO_THIRD_RUN','decision':'Gate fails: cycle0 p99 worsens; p95 reductions do not exceed baseline cycle variation in both cycles. Fewer SQL calls and lower cumulative CPU/profile totals alone do not establish retained benefit.','predeclared_gate':'both cycles same-direction meaningful end-to-end/burst/drain improvement beyond baseline cycle natural variation, correctness/budget/CPU/idle no regression; no SLA threshold','baseline_cycle_variation':variation,'after_minus_baseline':comparisons,'arms':arm,'confounds':['Baseline SQLite1260s idle tail overlaps MySQL process about159s, including coldidle and firstcycle about35s; audit/measurement-coactivity-note.json binds exact wall observations; separatePIDmetrics do not establish wholehost matchedexclusivity.','A ran later on existing engine/cache after contract checks; no randomized/repeated independent runs or planner counterfactual.','Same fixed eight-second500msProvider interval has throughput-dependent realized hits; compare actualcounts, not uniformly500mscohort assumptions.','Eight HTTP callers cap inflight and create externalqueue. Low producerCPU alone does not exclude caller cap as limitation; offer rate differs from HTTPresponse and DBadmission.','After P_S digest_lost grew93306 vsbaseline0; prepared/digest coverage incomplete, no missing=zero, no exact engineSQL count/reduction inferred.','One-Hz STATS interior profile has different sample coverage percycle and excludes boundaryreceipts; report means/samples, not total-time ratio alone.','Malloc counters exclude otherVM. Root vmmap supplies allocationmapping evidence only forbaseline cold/postcycles; no newaftervmmap, no objectorlongtermleak proof.','HistoricalPG25seconds difference remainsUNEXPLAINED; noPGworkload inC9.'], 'bounds':'2cycles perarm and one64target largecohort only; original190s unchanged; all36704targetsinwindoweacharm; nofailed/late/unknownremoved; no third workload or new DB observation'}
out['retained_runtime']={'revert_commit':'07634d20357f506f167ca4026ce0cd9337dfaa9e','final_normal_sha256':'b771b79a93b24025a037ca61c7056ea5a743ba52627a417dbee7f90d9d9efe44','byte_identical_to_frozen_be3_normal':True,'source_equivalence_receipt':'audit/final-normal-source-equivalence.json','build_receipt':'tests/final-07634d2-normal-build.json','retained_runtime_measurement':'baseline; rejected A CPU and latency are not finalcandidateperformance'}
p=b/'c9-before-after-comparison.json';assert not p.exists();p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'status':out['status'],'variation':variation,'deltas':comparisons,'peer':{k:v['peer'] for k,v in arm.items()},'CPU':{k:v['resource_totals'] for k,v in arm.items()}},indent=2))
